~()?\"']/g, ' ')\n .replace(/\\s+/g,:
~()?"']/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Nagy pontosságú kereső és szemantikus lekérdező motor
 */
export aszinkron függvény searchSentences(
  query:karakterlánc,
  szűrők: SearchFilterOptions = {}
): Promise<{ eredmények: SentenceItem[]; összesen:szám; szemanticMatch?: SemanticExplanationMatch[] }> {
  const all = várakozás loadSentences();
  const normalizedQuery = normalizeText(query);
  const queryTokens = normalizedQuery? normalizedQuery.split(' ').filter(Boolean) : [];

  const {
    cefr = 'minden',
    section = 'all',
    kategória = 'mind',
    alkategória = 'mind',
    nyelvtan = 'minden',
    formalitás = 'minden',
    határ = 50,
    eltolás = 0,
  } = szűrők;

  // Szűrőpassz
  let filtered = all.filter(s => {
    if (cefr !== 'mind' && s.cefr !== cefr) return false;
    if (szakasz !== 'összes' && s.section !==szakasz) return false;
    if (category !== 'all' && s.category !== kategória) return false;
    if (alkategória !== 'összes' && s.subcategory !== alkategória) return false;
    if (grammar !== 'all' && !s.grammar.toLowerCase().includes(grammar.toLowerCase())) return false;
    if (formalitás !== 'all' && s.formality.toLowerCase() !== formality.toLowerCase()) return false;
    return true;
  });

  if (!normalizedQuery) {
    const total = szűrt.hossz;
    const oldalszámozott = szűrt. szelet(eltolás, eltolás + határ);
    return { eredmények: oldalszámozott, összesen };
  }

  // Pontozási algoritmus
  interfaceScoredItem {
    item:SentenceItem;
    pontszám:szám;
    aspektus: SemanticExplanationMatch['matchedAspect'];
  }

  const pontozott: ScoredItem[] = [];

  for (const s of filtered) {
    legyen pontszám = 0;
    let matchedAspect: SemanticExplanationMatch['matchedAspect'] = 'magyar';

    const normEn = normalizeText(s.english);
    const normEg = normalizeText(s.arabicEg);
    const normFusha = normalizeText(s.arabicFusha);
    const normGrammar = normalizeText(s.grammar);
    const normPurpose = normalizeText(s.purpose);

    // Pontos teljes mondat egyezés
    if (normEn === normalizedQuery) {
      pontszám += 100;
      matchedAspect = 'angol';
    } else if (normEg === normalizedQuery) {
      pontszám += 95;
      matchedAspect = 'arab-pl.';
    } else if (normFusha === normalizedQuery) {
      pontszám += 90;
      matchedAspect = 'arab-fusha';
    }

    //A részstring tartalmazza
    if (normEn.includes(normalizedQuery)) {
      pontszám += 50;
      matchedAspect = 'angol';
    } else if (normEg.includes(normalizedQuery)) {
      pontszám += 45;
      matchedAspect = 'arab-pl.';
    } else if (normFusha.includes(normalizedQuery)) {
      pontszám += 40;
      matchedAspect = 'arab-fusha';
    } else if (normGrammar.includes(normalizedQuery)) {
      pontszám += 35;
      matchedAspect = 'nyelvtan';
    } else if (normPurpose.includes(normalizedQuery)) {
      pontszám += 30;
      matchedAspect = 'koncepció';
    }

    // Token match
    legyen tokenMatches = 0;
    for (const token of queryTokens) {
      if (normEn.includes(token)) tokenMatches += 5;
      if (normEg.includes(token)) tokenMatches += 4;
      if (normFusha.includes(token)) tokenMatches += 3;
      if (s.vocabulary.some(v => normalizeText(v).includes(token))) tokenMatches += 4;
      if (s.tags.some(t => normalizeText(t).includes(token))) tokenMatches += 3;
    }
    pontszám += tokenMatches;

    if (pontszám > 0) {
      scored.push({ item: s, score, aspekt: matchedAspect });
    }
  }

  scored.sort((a, b) => b.score - a.score);

  // A szemantikai magyarázat megfelel a legfontosabb elemeknek
  const szemanticMatches: SemanticExplanationMatch[] = scored.slice(0, 5).map(s => {
    legyen árnyalat = '';
    if (s.item.grammar.toLowerCase().includes('past folyamatos')) {
      nuance = 'A folytonos múlt idő azt mutatja, hogy egy esemény a múlt egy adott időpontjában folyamatban volt.';
    } else if (s.item.grammar.toLowerCase().includes('present perfect folyamatos')) {
      nüansz = 'A jelen tökéletes folyamatos idő a múltból származó időt hangsúlyozza, és a beszéd pillanatáig folytatódik.';
    } else if (s.item.grammar.toLowerCase().includes('future perfect')) {
      nuance = 'A jövőbeli tökéletes idő azt fejezi ki, hogy egy esemény egy adott időpont előtt befejeződik a jövőben.';
    } else if (s.item.grammar.toLowerCase().includes('indirect')) {
      nuance = 'A közvetett megkeresés formája a diplomáciai etikett csúcsa az angol kommunikációban.';
    }
    return {
      mondat: s.item,
      Hasonlósági Pontszám: Math.min(100, s.score),
      árnyalat MagyarázatAr: árnyalat,
      matchedAspect: s.aspect,
    };
  });

  const összesen = pontozott. hossza;
  const oldalszámozott = pontozott.szelet(eltolás, eltolás + határ).map(s => s.item);

  return {
    találatok: oldalszámozott,
    összesen,
    szemantikai egyezések,
  };
}

